-- stray – englische Texte (Teil 29), Schlüssel = deutscher Originaltext
local _, ns = ...
local E = ns.LocaleEN

-- Ausblenden und Text (hidetext.lua)
E["Zonentext ausblenden"] = "Hide zone text"
E["Die großen Gebietsnamen beim Betreten einer Zone oder eines Unterbereichs erscheinen nicht mehr."] = "The large area names shown when you enter a zone or subzone no longer appear."
E["Schadenszahlen im Porträt ausblenden"] = "Hide damage numbers on portraits"
E["Die großen Schadens- und Heilungszahlen, die im Porträt von Spieler und Begleiter aufblitzen, verschwinden. Der Lebensbalken bleibt unverändert."] = "The large damage and healing numbers that flash on the player and pet portraits disappear. The health bar is unchanged."
E["Tastenkürzel auf Aktionsleisten ausblenden"] = "Hide key bindings on action bars"
E["Blendet die Tastenbeschriftung (z. B. „1“, „S-F“) auf Blizzards Aktionsleisten, Begleiter- und Haltungsleiste aus. Die Belegung selbst bleibt erhalten."] = "Hides the key labels (e.g. \"1\", \"S-F\") on Blizzard's action bars, pet bar and stance bar. The bindings themselves are kept."
E["Makronamen auf Aktionsleisten ausblenden"] = "Hide macro names on action bars"
E["Blendet die Makronamen auf den Knöpfen von Blizzards Aktionsleisten aus. Die Makros bleiben unverändert."] = "Hides the macro names on the buttons of Blizzard's action bars. The macros themselves are unchanged."
E["„Talking Head“-Fenster ausblenden"] = "Hide Talking Head window"
E["Das Fenster mit dem sprechenden NPC-Kopf erscheint nicht mehr. Ein laufendes Fenster wird sofort geschlossen."] = "The window with the talking NPC head no longer appears. A running window is closed immediately."
E["Ereignis-Banner (Alerts) ausblenden"] = "Hide event banners (alerts)"
E["Blendet Blizzards Hinweis-Banner am Bildschirmrand aus: Erfolge, Beute, Währungen, neue Rezepte, Reittiere, Haustiere, Spielzeuge u. a. Fehler und Warnungen sind nicht betroffen.\n\nBeim Ausschalten erscheinen höchstens die wenigen zwischenzeitlich gesammelten Banner nachträglich."] = "Hides Blizzard's notification banners at the screen edge: achievements, loot, currencies, new recipes, mounts, pets, toys and more. Errors and warnings are not affected.\n\nWhen you switch this off again, at most the few banners collected in the meantime show up late."
E["Boss-Banner ausblenden"] = "Hide boss banner"
E["Das große Banner nach einem Bosskampf („Besiegt“) und die dazugehörige Beuteanzeige erscheinen nicht mehr. Die Beute selbst bleibt unverändert."] = "The large banner after a boss fight (\"Defeated\") and its loot display no longer appear. The loot itself is unchanged."
E["Gryphon-Verzierungen ausblenden"] = "Hide gryphon ornaments"
E["Blendet die Gryphonen links und rechts der Hauptaktionsleiste aus."] = "Hides the gryphons on the left and right of the main action bar."
E["Ruhe-Animation („Zzz“) ausblenden"] = "Hide rest animation (\"Zzz\")"
E["Blendet die schlafende Ruhe-Animation im Spielerporträt in Städten und Gasthäusern aus. Beim Ausschalten wirkt es wieder, sobald sich dein Ruhestatus ändert."] = "Hides the sleeping rest animation on the player portrait in cities and inns. When switched off, it returns as soon as your rest status changes."
E["Raidgruppen-Beschriftungen ausblenden"] = "Hide raid group labels"
E["Blendet die Titel „Gruppe 1“, „Gruppe 2“ … über den Gruppen der Blizzard-Raidfenster aus."] = "Hides the \"Group 1\", \"Group 2\" ... titles above the groups in Blizzard's raid frames."
E["Erst die Option direkt darüber einschalten."] = "Turn on the option directly above first."
E["Post-Text größer"] = "Larger mail text"
E["Zeigt den Text im Postfach (Lesen und Schreiben) in der darunter eingestellten Schriftgröße."] = "Shows the text in your mailbox (reading and writing) in the font size set below."
E["Post-Schriftgröße"] = "Mail font size"
E["Schriftgröße für Post-Texte."] = "Font size for mail text."
E["Quest-Text größer"] = "Larger quest text"
E["Zeigt Questbeschreibung, Ziele, Belohnungstext, NPC-Begrüßung und Fortschrittstext in der darunter eingestellten Schriftgröße. Wirkt ab dem nächsten Öffnen eines Questfensters."] = "Shows quest description, objectives, reward text, NPC greeting and progress text in the font size set below. Takes effect the next time you open a quest window."
E["Quest-Schriftgröße"] = "Quest font size"
E["Schriftgröße für Quest-Texte."] = "Font size for quest text."
E["Buch-Text größer"] = "Larger book text"
E["Zeigt den Text von Büchern, Briefen und Tafeln in der darunter eingestellten Schriftgröße. Wirkt ab dem nächsten Öffnen."] = "Shows the text of books, letters and plaques in the font size set below. Takes effect the next time you open one."
E["Buch-Schriftgröße"] = "Book font size"
E["Schriftgröße für Buch-Texte."] = "Font size for book text."
